document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll(".animate-on-scroll");if(0===n.length)return void console.warn("No se encontraron elementos con la clase 'animate-on-scroll'");const e=()=>{n.forEach(n=>{if(!n)return;n.getBoundingClientRect().top<.8*window.innerHeight&&!n.classList.contains("animated")&&(n.classList.add("animated"),n.style.opacity="1",n.style.transform="translateY(0)")})};window.addEventListener("scroll",()=>{requestAnimationFrame(e)}),e()});